const fs=require('fs'),crypto=require('crypto');
const katex=require(process.cwd()+'/web/static/vendor/katex/katex.min.js');
const input='corpus/public/reader/icml2023-decoder/author-transcripts-discussion-extra.json';
const x=JSON.parse(fs.readFileSync(input,'utf8'));let checked=0;const errors=[];
const rx=/\$\$[\s\S]*?\$\$|(?<!\$)\$(?!\$)[^\n$]+\$/g;
for(const row of x.transcripts)for(const field of ['original_statement_md','original_proof_md']){
 let m;rx.lastIndex=0;while((m=rx.exec(row[field]))!==null){const count=m[0].startsWith('$$')?2:1;const tex=m[0].slice(count,-count);checked++;
  try{katex.renderToString(tex,{throwOnError:true,strict:'ignore',trust:false,displayMode:true});}
  catch(error){errors.push({key:row.key,field,tex,error:String(error)});}
 }
}
const fingerprint=p=>crypto.createHash('sha256').update(fs.readFileSync(p)).digest('hex');
const report={status:errors.length?'failed':'passed',scope:'formal_author_transcription_format_and_actual_katex_only_not_mathematical_acceptance',source_id:x.source_id,input_sha256:fingerprint(input),source_sha256:x.source_sha256,segments:x.transcripts.length,author_characters:x.transcripts.reduce((n,r)=>n+r.original_statement_md.length+r.original_proof_md.length,0),checked,errors,source_evidence_sha256:x.source_evidence_sha256,visual_review:x.visual_review,validator_source:fs.readFileSync(__filename,'utf8'),katex_sha256:fingerprint('web/static/vendor/katex/katex.min.js')};
fs.writeFileSync('reader/evidence/twelve-paper-20261001/f06-discussion-source-transcription-checks.json',JSON.stringify(report,null,2)+'\n');
console.log(JSON.stringify({status:report.status,checked,errors}));process.exitCode=errors.length?1:0;
